#!/usr/bin/env bash
# generated by AI (GitHub Copilot, DeepSeek V4 Flash Vision Exp)
#
# Install this app into an existing Nextcloud instance.
#
# Usage:
#   sudo bash scripts/install-app.sh /var/www/nextcloud
#   sudo bash scripts/install-app.sh /var/www/nextcloud --web-user http
#   bash scripts/install-app.sh /var/www/nextcloud --no-enable   # copy only
#
# The target must be a Nextcloud root (it contains occ and config/config.php).
# The app is copied to <root>/custom_apps/upm unless --app-dir is given.
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="$(dirname "$SCRIPT_DIR")"
APP_ID="upm"

WEB_USER="www-data"
APP_DIR=""
BUILD=0
ENABLE=1
NC_ROOT=""

usage() {
	cat <<'EOF'
Install the UPM app into an existing Nextcloud instance.

Usage:
  sudo bash scripts/install-app.sh /path/to/nextcloud [options]

Options:
  --web-user USER   Web server user (default: www-data; Arch: http)
  --app-dir PATH    Target directory (default: <root>/custom_apps/upm)
  --build           Rebuild js/upm.js before copying
  --no-enable       Copy the files but do not run occ app:enable
  -h, --help        Show this help
EOF
}

die() { echo "error: $*" >&2; exit 1; }

while [ $# -gt 0 ]; do
	case "$1" in
		--web-user)
			[ $# -ge 2 ] || die "--web-user needs a value"
			WEB_USER="$2"
			shift 2
			;;
		--app-dir)
			[ $# -ge 2 ] || die "--app-dir needs a value"
			APP_DIR="$2"
			shift 2
			;;
		--build) BUILD=1; shift ;;
		--no-enable) ENABLE=0; shift ;;
		-h|--help) usage; exit 0 ;;
		-*) die "unknown option: $1 (try --help)" ;;
		*)
			[ -z "$NC_ROOT" ] || die "only one Nextcloud root may be given"
			NC_ROOT="$1"
			shift
			;;
	esac
done

[ -n "$NC_ROOT" ] || { usage >&2; exit 1; }
[ -d "$NC_ROOT" ] || die "not a directory: $NC_ROOT"
NC_ROOT="$(cd "$NC_ROOT" && pwd)"
[ -f "$NC_ROOT/occ" ] || die "$NC_ROOT does not look like a Nextcloud root (occ missing)"
[ -f "$NC_ROOT/config/config.php" ] || die "$NC_ROOT/config/config.php not found"
[ -f "$PROJECT_ROOT/appinfo/info.xml" ] || die "appinfo/info.xml missing; run this from the app checkout"
grep -q "<id>${APP_ID}</id>" "$PROJECT_ROOT/appinfo/info.xml" ||
	die "unexpected app id in appinfo/info.xml (expected ${APP_ID})"

APP_DIR="${APP_DIR:-$NC_ROOT/custom_apps/$APP_ID}"

if [ "$BUILD" -eq 1 ]; then
	bash "$PROJECT_ROOT/scripts/build-frontend.sh"
fi
[ -f "$PROJECT_ROOT/js/upm.js" ] ||
	die "js/upm.js is missing; run 'bash scripts/build-frontend.sh' or pass --build"

# Never clobber a different app that happens to live at the target path.
if [ -f "$APP_DIR/appinfo/info.xml" ]; then
	grep -q "<id>${APP_ID}</id>" "$APP_DIR/appinfo/info.xml" ||
		die "$APP_DIR contains a different app; refusing to overwrite it"
fi

echo "==> Installing ${APP_ID} into $APP_DIR"
mkdir -p "$APP_DIR"

EXCLUDES=(
	--exclude node_modules
	--exclude src
	--exclude tests
	--exclude doc
	--exclude docs
	--exclude scripts
	--exclude tmp
	--exclude .dev
	--exclude .git
	--exclude .github
	--exclude .vscode
	--exclude img/screenshots
	--exclude package.json
	--exclude package-lock.json
	--exclude tsconfig.json
	--exclude vite.config.ts
	--exclude vitest.config.ts
	--exclude Makefile
	--exclude .gitignore
	--exclude .editorconfig
)

if command -v rsync >/dev/null 2>&1; then
	rsync -a --delete --delete-excluded "${EXCLUDES[@]}" "$PROJECT_ROOT/" "$APP_DIR/"
else
	echo "note: rsync not found; copying the app directories with cp"
	find "$APP_DIR" -mindepth 1 -maxdepth 1 -exec rm -rf {} +
	(
		cd "$PROJECT_ROOT"
		cp -a appinfo lib js img templates composer.json LICENSE README.md "$APP_DIR/"
	)
fi

[ -f "$APP_DIR/js/upm.js" ] || die "copy failed: $APP_DIR/js/upm.js is missing"

if [ "$(id -u)" -eq 0 ]; then
	echo "==> Fixing ownership ($WEB_USER)"
	chown -R "$WEB_USER:$WEB_USER" "$APP_DIR"
	chmod -R u=rwX,go=rX "$APP_DIR"
	# Nextcloud requires the install path (custom_apps) to be writable.
	chown "$WEB_USER:$WEB_USER" "$(dirname "$APP_DIR")"
else
	echo "note: not running as root; skipping ownership fixes"
	echo "      the web server user ($WEB_USER) must be able to read $APP_DIR"
fi

if [ "$ENABLE" -eq 1 ]; then
	echo "==> Enabling ${APP_ID}"
	if [ "$(id -u)" -eq 0 ]; then
		command -v runuser >/dev/null 2>&1 ||
			die "runuser not found; run: sudo -u $WEB_USER php $NC_ROOT/occ app:enable $APP_ID"
		run_occ() { runuser -u "$WEB_USER" -- php "$NC_ROOT/occ" "$@"; }
	else
		run_occ() { php "$NC_ROOT/occ" "$@"; }
	fi

	run_occ app:enable "$APP_ID" || die "occ app:enable $APP_ID failed"
	run_occ app:list | grep -q "$APP_ID" || die "$APP_ID is not listed after enabling"
fi

echo ""
echo "Done. Open /index.php/apps/${APP_ID}/ in your Nextcloud and sign in."
echo "Databases are stored under the user's files (default folder: upm/)."
